mod audit_issuer{include!(concat!(env!("CARGO_MANIFEST_DIR"),"/../../audit/exec/agent-tab-fixture.rs"));}
fn issuer()->(String,std::sync::Arc<std::sync::Mutex<audit_issuer::Issuer>>){let kp=audit_issuer::Kp::generate(&mut blind_rsa_signatures::DefaultRng,2048).unwrap();let state=std::sync::Arc::new(std::sync::Mutex::new(audit_issuer::Issuer{kp,key_id:"explicit-fixture-key".into(),issue_calls:0,mode:0,issued:std::collections::HashSet::new(),spent:std::collections::HashSet::new()}));(audit_issuer::serve(state.clone()),state)}
fn tabfile(dir:&std::path::Path)->PathBuf{dir.join("ledger.tab.json")}
fn mcp_fixture_call(dir:&std::path::Path,name:&str,args:serde_json::Value)->serde_json::Value{use std::io::Write;let mut p=Command::new(PathBuf::from(std::env::var("KAGE_BIN_DIR").unwrap()).join("x402z-mcp")).env_clear().env("PATH",std::env::var("PATH").unwrap()).env("X402Z_AGENT_WALLET_DIR",dir.join("unused-wallet")).env("X402Z_AGENT_LEDGER",dir.join("ledger.json")).env("X402Z_AGENT_LEDGER_KEY","19".repeat(32)).env("X402Z_AGENT_ALLOWED_HOSTS","127.0.0.1").env("X402Z_AGENT_DAILY_CAP_ZAT","5000000").stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();let pid=p.id();writeln!(p.stdin.as_mut().unwrap(),"{}",serde_json::json!({"jsonrpc":"2.0","id":1,"method":"tools/call","params":{"name":name,"arguments":args}})).unwrap();drop(p.stdin.take());let o=p.wait_with_output().unwrap();println!("MCP PID {pid} exited and reaped");assert!(o.status.success());let v:serde_json::Value=serde_json::from_slice(&o.stdout).unwrap();assert_eq!(v["id"],1);assert_eq!(v["jsonrpc"],"2.0");v["result"].clone()}
#[test]
fn audit_cli_external_tab_real_blind_rsa_and_mcp_collection(){use x402z_agent::tab;let dir=temp("tab-cli");let(url,state)=issuer();let out=cli(&dir,&["tab-buy","3","--external"],&[("X402Z_TARGET_URL",Some(&url))]);assert_eq!(out.status.code(),Some(0));let v:serde_json::Value=serde_json::from_slice(&out.stdout).unwrap();let p=&v["pending"];assert_eq!(p["tokens"],3);assert_eq!(p["amountZat"],300000);assert_eq!(p["memoNonce"],audit_issuer::NONCE);assert_eq!(p["payTo"],audit_issuer::PAY_TO);assert!(p["keyId"].is_string());assert!(p["expiresAt"].is_u64());assert_eq!(p["paymentUri"],x402z_protocol::zip321_uri(audit_issuer::PAY_TO,300000,audit_issuer::NONCE));assert!(!dir.join("wallet-never-opened").exists());mark(316);
    // Mark the external payment as a clearly labelled post-broadcast fixture, then use MCP's
    // actual resume path. The issuer generates real blind-RSA signatures, not canned tokens.
    {let mut file=tab::TabFile::open(&tabfile(&dir),&LedgerKey::from_bytes([25;32])).unwrap();file.state.pending[0].txid=Some("ab".repeat(32));file.save().unwrap();}
    let r=mcp_fixture_call(&dir,"tab_fetch",serde_json::json!({"url":url,"buy":3}));assert_eq!(r["isError"],false);let p=&r["structuredContent"];assert_eq!(p["status"],"tab_pending");assert_eq!(p["tokens"],3);assert_eq!(p["txid"],"ab".repeat(32));assert_eq!(p["memoNonce"],audit_issuer::NONCE);assert_eq!(p["keyId"],"explicit-fixture-key");assert_eq!(state.lock().unwrap().issue_calls,1);
    let r=mcp_fixture_call(&dir,"tab_fetch",serde_json::json!({"url":url,"buy":3}));assert_eq!(r["isError"],false);let p=&r["structuredContent"];assert_eq!(p["status"],200);assert_eq!(p["paidWith"],"tab_token");assert_eq!(p["remainingTokens"],2);assert_eq!(p["settlement"]["success"],true);assert_eq!(state.lock().unwrap().issue_calls,2);assert_eq!(tab::TabFile::open(&tabfile(&dir),&LedgerKey::from_bytes([25;32])).unwrap().state.pending.len(),0);mark(380);mark(381);
    let out=cli(&dir,&["tab-fetch"],&[("X402Z_TARGET_URL",Some(&url))]);assert_eq!(out.status.code(),Some(0));assert_eq!(serde_json::from_slice::<serde_json::Value>(&out.stdout).unwrap(),serde_json::json!({"quote":"paid by tab"}));let stderr=String::from_utf8(out.stderr).unwrap();assert!(stderr.contains("X-PAYMENT-RESPONSE: success=true"));assert!(stderr.contains("1 token(s) left"));assert_eq!(tab::TabFile::open(&tabfile(&dir),&LedgerKey::from_bytes([25;32])).unwrap().state.tokens.len(),1);mark(335);
    drop(state);std::fs::remove_dir_all(dir).unwrap();
}
#[test]
fn audit_cli_tab_redeem_202_then_verified_tokens(){use x402z_agent::tab;let dir=temp("tab-redeem");let(url,state)=issuer();check(cli(&dir,&["tab-buy","2","--external"],&[("X402Z_TARGET_URL",Some(&url))]),0,&["then run"]);let out=cli(&dir,&["tab-redeem",&"ab".repeat(32)],&[]);assert_eq!(out.status.code(),Some(0));let v:serde_json::Value=serde_json::from_slice(&out.stdout).unwrap();assert_eq!(v["tab"]["tokens"],2);let file=tab::TabFile::open(&tabfile(&dir),&LedgerKey::from_bytes([25;32])).unwrap();assert_eq!(file.state.tokens.len(),2);assert!(file.state.pending.is_empty());assert_eq!(state.lock().unwrap().issue_calls,2);drop(file);let l=LedgerFile::load(&dir.join("ledger.json"),&LedgerKey::from_bytes([25;32])).unwrap();assert_eq!(l.data.audit.iter().filter(|e|e.txid.is_some()).count(),1);assert_eq!(l.guard("agent-1",&audit_cfg(&dir).policy,timestamp()).spent_today("agent-1",timestamp()),200000);mark(326);drop(l);std::fs::remove_dir_all(dir).unwrap();}
fn sample_offer()->serde_json::Value{let kp=audit_issuer::Kp::generate(&mut blind_rsa_signatures::DefaultRng,2048).unwrap();serde_json::json!({"scheme":"zcash-shielded-tab","suite":"RSABSSA-SHA384-PSS-Randomized","keyId":"explicit-fixture-key","publicKey":x402z_protocol::b64(&kp.pk.to_spki().unwrap()),"unitPriceZat":100000,"maxTokens":20,"issuePath":"/tab/issue","epochEndsAt":4000000000u64})}
#[test]
fn audit_cli_invalid_tab_offers_and_pins(){use x402z_agent::tab;for id in [319,320,321,322,323,324]{let dir=temp(&format!("tab-offer-{id}"));let foreign=http_fixture(|_|raw_http("500 Internal Server Error","must not be requested"));let mut b=required_body();let mut offer=sample_offer();match id{320=>offer["unitPriceZat"]=serde_json::json!(u64::MAX),323=>offer["epochEndsAt"]=serde_json::json!(timestamp()+1),324=>offer["issuePath"]=foreign.url.clone().into(),_=>{}}if id!=321{b["accepts"][0]["extra"]["tab"]=offer;}
    let server=http_fixture(move |_|raw_http("402 Payment Required",&b.to_string()));if id==322{let mut f=tab::TabFile::open(&tabfile(&dir),&LedgerKey::from_bytes([25;32])).unwrap();let origin=server.url.trim_end_matches("/api/quote");f.state.pins.push(tab::KeyPin{origin:origin.into(),key_id:"earlier-pinned-key".into(),epoch_ends_at:4000000000});f.save().unwrap();}
    let args=match id{319=>vec!["tab-buy","25","--external"],320=>vec!["tab-buy","2","--external"],_=>vec!["tab-buy","1","--external"]};let code=if [319,320].contains(&id){2}else{1};let text=match id{319=>"a tab holds 1 to 20 tokens on this server; asked for",320=>"tab price overflows",321=>"this server does not offer a Kage Tab (no extra.tab in its 402)",322=>"still in its epoch",323=>"not buying a tab that may never be issued",_=>"another origin"};check(cli(&dir,&args,&[("X402Z_TARGET_URL",Some(&server.url))]),code,&[text]);if id==322{check(cli(&dir,&["tab-buy","1"],&[("X402Z_TARGET_URL",Some(&server.url))]),1,&["still in its epoch","Nothing was paid."]);}let l=LedgerFile::load(&dir.join("ledger.json"),&LedgerKey::from_bytes([25;32])).unwrap();assert!(l.data.audit.is_empty());assert_eq!(foreign.hits.load(std::sync::atomic::Ordering::SeqCst),0);assert!(!dir.join("wallet-never-opened").exists());mark(id);drop(server);drop(foreign);std::fs::remove_dir_all(dir).unwrap();}
    let dir=temp("tab-no-pending");check(cli(&dir,&["tab-redeem",&"ab".repeat(32)],&[]),2,&["no pending tab purchase; start one with"]);mark(329);std::fs::remove_dir_all(dir).unwrap();}
#[test]
fn audit_tab_invalid_issue_replies_and_timeout(){use x402z_agent::tab;for mode in [1,2,3,4]{let dir=temp(&format!("tab-response-{mode}"));let(url,state)=issuer();state.lock().unwrap().mode=mode;state.lock().unwrap().issue_calls=1;check(cli(&dir,&["tab-buy","1","--external"],&[("X402Z_TARGET_URL",Some(&url))]),0,&["then run"]);let expected=match mode{1|2=>"tab issue returned",3=>"blind signature does not verify",_=>"not confirmed for the tab before timeout"};check(cli(&dir,&["tab-redeem",&"ab".repeat(32)],&[("X402Z_AGENT_CONFIRM_TIMEOUT_SECS",Some("0"))]),1,&[expected]);let f=tab::TabFile::open(&tabfile(&dir),&LedgerKey::from_bytes([25;32])).unwrap();assert!(f.state.tokens.is_empty());assert_eq!(f.state.pending.len(),1);drop(f);let l=LedgerFile::load(&dir.join("ledger.json"),&LedgerKey::from_bytes([25;32])).unwrap();assert_eq!(l.data.audit.iter().filter(|e|e.txid.is_some()).count(),1);mark(match mode{1|2=>332,3=>333,_=>334});drop(l);std::fs::remove_dir_all(dir).unwrap();}}
fn fake_token(origin:&str,expires:u64)->x402z_agent::tab::StoredToken{x402z_agent::tab::StoredToken{origin:origin.into(),key_id:"explicit-fixture-key".into(),epoch_ends_at:expires,grace_secs:0,msg:"AA==".into(),randomizer:x402z_protocol::b64(&[1;32]),sig:"AA==".into()}}
#[test]
fn audit_cli_tab_transport_failure_and_populated_status(){use x402z_agent::tab;for id in [339,340,341,343]{let dir=temp(&format!("tab-transport-{id}"));let(server,url)=if id==340{let l=std::net::TcpListener::bind("127.0.0.1:0").unwrap();let addr=l.local_addr().unwrap();drop(l);(None,format!("http://{addr}/api/quote"))}else{let s=http_fixture(move |_|if id==339{let h=x402z_protocol::encode_header(&x402z_protocol::SettlementResponse::failed("nonce_already_used"));format!("HTTP/1.1 402 Payment Required\r\nX-PAYMENT-RESPONSE: {h}\r\nContent-Length: 0\r\nConnection: close\r\n\r\n").into_bytes()}else{b"HTTP/1.1 200 OK\r\nContent-Length: 1000\r\nConnection: close\r\n\r\n".to_vec()});let url=s.url.clone();(Some(s),url)};let origin=url.trim_end_matches("/api/quote");{let mut f=tab::TabFile::open(&tabfile(&dir),&LedgerKey::from_bytes([25;32])).unwrap();f.state.tokens.push(fake_token(origin,timestamp()+900));if id==343{f.state.tokens.push(fake_token(origin,timestamp()-1));f.state.pending.push(tab::PendingPurchase{url:url.clone(),n:3,amount_zat:300000,pay_to:audit_issuer::PAY_TO.into(),memo_nonce:"x402z-pending-fixture".into(),expires_at:4000000000,payment_uri:"zcash:explicit-fixture".into(),offer:serde_json::from_value(sample_offer()).unwrap(),created_at:timestamp(),txid:None});}f.save().unwrap();}
    if id==343{let o=cli(&dir,&["tab-status"],&[]);assert_eq!(o.status.code(),Some(0));let v:serde_json::Value=serde_json::from_slice(&o.stdout).unwrap();assert_eq!(v["tokens"][origin],1);assert_eq!(v["pending"][0],serde_json::json!({"memoNonce":"x402z-pending-fixture","tokens":3,"amountZat":300000,"expiresAt":4000000000u64}));}else{let o=cli(&dir,&["tab-fetch"],&[("X402Z_TARGET_URL",Some(&url))]);check(o,if id==339{5}else{1},if id==339{&["server refused the tab token"]}else if id==340{&["with a tab token failed"]}else{&["reading the answer"]});let f=tab::TabFile::open(&tabfile(&dir),&LedgerKey::from_bytes([25;32])).unwrap();assert_eq!(f.state.tokens.len(),if id==340{1}else{0});}assert!(!dir.join("wallet-never-opened").exists());mark(id);drop(server);std::fs::remove_dir_all(dir).unwrap();}}
