#[test]
fn audit_tab_rotation_retains_purchase_and_refuses_moved_path(){use x402z_agent::tab;for moved in [false,true]{let dir=temp(if moved{"moved-issue"}else{"rotated-issue"});let state=std::sync::Arc::new(std::sync::Mutex::new(audit_rotation::Issuer{key:audit_rotation::key("k1",4000000000),rotate_on_issue:None,issue_calls:0,moved,post_paths:vec![]}));let url=audit_rotation::serve(state.clone());check(cli(&dir,&["tab-buy","3","--external"],&[("X402Z_TARGET_URL",Some(&url))]),0,&["then run"]);{let mut f=tab::TabFile::open(&tabfile(&dir),&LedgerKey::from_bytes([25;32])).unwrap();assert_eq!(f.state.pending[0].offer.key_id,"k1");f.state.pins[0].epoch_ends_at=0;f.save().unwrap();}state.lock().unwrap().rotate_on_issue=Some(audit_rotation::key("k2",4000000000));let out=cli(&dir,&["tab-redeem",&"ab".repeat(32)],&[]);if moved{check(out,1,&["the rotated tab offer moved its issuePath; not following it"]);assert_eq!(state.lock().unwrap().post_paths.len(),1);assert!(state.lock().unwrap().post_paths.iter().all(|p|!p.contains("/tab/changed")));mark(331);}else{assert_eq!(out.status.code(),Some(0));let v:serde_json::Value=serde_json::from_slice(&out.stdout).unwrap();assert_eq!(v["tab"]["keyId"],"k1");assert_eq!(v["tab"]["tokens"],3);assert_eq!(state.lock().unwrap().issue_calls,2);let f=tab::TabFile::open(&tabfile(&dir),&LedgerKey::from_bytes([25;32])).unwrap();assert_eq!(f.state.tokens.len(),3);assert!(f.state.tokens.iter().all(|t|t.key_id=="k2"));drop(f);mark(330);}let l=LedgerFile::load(&dir.join("ledger.json"),&LedgerKey::from_bytes([25;32])).unwrap();assert_eq!(l.data.audit.iter().filter(|e|e.txid.is_some()).count(),1);assert_eq!(l.guard("agent-1",&audit_cfg(&dir).policy,timestamp()).spent_today("agent-1",timestamp()),300000);std::fs::remove_dir_all(dir).unwrap();}}
